using namespace std;

struct Ballot { vector<int> prefs; };

bool isValid(string c) {
    if (c.length() != 15) return false;
    int sum = 0, count = 0;
    for (int i = 0; i < 14; i++) {
        if (isdigit(c[i])) {
            int d = c[i] - '0';
            count++;
            sum += (count % 2 != 0) ? d * 3 : d;
        }
    }
    return ((10 - (sum % 10)) % 10) == (c[14] - '0');
}

int main() {
    int numC, numB; cin >> numC >> numB;
    vector<string> names(numC);
    map<string, int> nameToIndex;
    for (int i = 0; i < numC; i++) { cin >> names[i]; nameToIndex[names[i]] = i; }
    vector<Ballot> ballots;
    for (int i = 0; i < numB; i++) {
        string code; cin >> code;
        bool valid = isValid(code);
        Ballot b;
        for (int j = 0; j < numC; j++) {
            string p; cin >> p;
            if (valid) b.prefs.push_back(nameToIndex[p]);
        }
        if (valid) ballots.push_back(b);
    }
    vector<bool> eliminated(numC, false);
    while (true) {
        vector<int> votes(numC, 0);
        for (auto &b : ballots) {
            for (int p : b.prefs) {
                if (!eliminated[p]) { votes[p]++; break; }
            }
        }
        int total = ballots.size(), winner = -1, minVotes = total + 1, loser = -1;
        for (int i = 0; i < numC; i++) {
            if (!eliminated[i]) {
                if (votes[i] > total / 2) winner = i;
                if (votes[i] < minVotes) { minVotes = votes[i]; loser = i; }
            }
        }
        if (winner != -1) { cout << names[winner] << endl; break; }
        eliminated[loser] = true;
    }
    return 0;
}

#include <iostream>
using namespace std;
struct Node { int val; Node* next; };
struct Stack {
    Node* top = nullptr;
    void push(int x) { Node* n = new Node{x, top}; top = n; }
    void pop() { if(top) { Node* t = top; top = top->next; delete t; } }
    void reverse() {
        Node *prev = nullptr, *curr = top, *next;
        while(curr) { next = curr->next; curr->next = prev; prev = curr; curr = next; }
        top = prev;
    }
    void print() {
        Node* c = top; while(c) { cout << c->val << (c->next ? " " : ""); c = c->next; } cout << endl;
    }
};
int main() {
    Stack s; int op, val; while(cin >> op) {
        if(op == 2) { cin >> val; s.push(val); }
        else if(op == 10) s.print();
    }
    return 0;
}

