using namespace std;
int dx[]={1,-1,0,0}, dy[]={0,0,1,-1};
int main() {
    int n,m; cin>>n>>m;
    vector<vector<int>> g(n+1,vector<int>(m+1)), d(n+1,vector<int>(m+1,0));
    vector<vector<pair<int,int>>> pr(n+1,vector<pair<int,int>>(m+1));
    for(int i=1;i<=n;i++)for(int j=1;j<=m;j++)cin>>g[i][j];
    int xs,ys,xf,yf; cin>>xs>>ys>>xf>>yf;
    queue<pair<int,int>> q; q.push({xs,ys}); d[xs][ys]=1;
    while(!q.empty()){
        auto c = q.front(); q.pop();
        if(c.first==xf && c.second==yf) break;
        for(int i=0;i<4;i++){
            int nx=c.first+dx[i], ny=c.second+dy[i];
            if(nx>=1&&nx<=n&&ny>=1&&ny<=m&&g[nx][ny]==0&&d[nx][ny]==0){
                d[nx][ny]=d[c.first][c.second]+1; pr[nx][ny]=c; q.push({nx,ny});
            }
        }
    }
    if(!d[xf][yf]) cout<<"Nu exista drum!";
    else {
        cout<<d[xf][yf]<<endl;
        vector<pair<int,int>> p; for(pair<int,int> c={xf,yf}; c!=make_pair(0,0); c=pr[c.first][c.second]) p.push_back(c);
        reverse(p.begin(),p.end()); for(auto i:p) cout<<i.first<<" "<<i.second<<endl;
    }
    return 0;
}

